-- Adds real logo images for Davines and Living Proof.
-- Images are resized to 300px max dimension and embedded as base64 data URIs.
-- If a brand name below doesn't match exactly what's in your Brands list, edit it in
-- the admin panel afterwards (Brands & modules -> edit -> paste logo URL), or fix the
-- name here before running.

update brands set logo_url = 'data:image/png;base64,' where name = 'Davines';

update brands set logo_url = 'data:image/png;base64,' where name = 'Living Proof';
